const body = $input.item.json.body || $input.item.json;
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const db = `${prj}/IMPAR_OS/database/impar.db`;
const { execSync } = require('child_process');
const ts = new Date().toISOString();
const action = (body.action||'unknown').replace(/'/g,"''").substring(0,100);
const status = (body.status||'unknown').replace(/'/g,"''").substring(0,20);
const origin = (body.origin||'api').replace(/'/g,"''").substring(0,50);
const summary = (body.output_summary||'').replace(/'/g,"''").substring(0,500);
const ai_used = body.ai_used ? 1 : 0;
const duration = parseInt(body.duration_ms||0);
try {
  execSync(`sqlite3 "${db}" "INSERT INTO executions (run_id,timestamp,origin,action,duration_ms,status,output_summary,exit_code,ai_used,cache_used) VALUES ('$(uuidgen 2>/dev/null || echo $$)','${ts}','${origin}','${action}',${duration},'${status}','${summary}',0,${ai_used},0);"`, {timeout:5000});
} catch(e) { return [{ json: { error: e.message.substring(0,200), ai_used: false } }]; }
return [{ json: { ok: true, logged: true, ai_used: false, timestamp: ts } }];
